'use strict';

// MODULES //

var tape = require( 'tape' );
var Number = require( '@stdlib/number-ctor' );
var isnanf = require( './../lib' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof isnanf, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function returns `true` if provided `NaN`', function test( t ) {
	t.strictEqual( isnanf( NaN ), true, 'returns expected value' );
	t.end();
});

tape( 'the function returns `false` if not provided `NaN`', function test( t ) {
	var values;
	var i;

	values = [
		'5',
		5.0,
		true,
		false,
		null,
		void 0,
		[],
		{},
		function noop() {},
		new Number( NaN )
	];

	for ( i = 0; i < values.length; i++ ) {
		t.strictEqual( isnanf( values[i] ), false, 'returns expected value when provided ' + values[ i ] );
	}
	t.end();
